-- Changelog: meldingen voor acties, toolbox, planning en uren.
-- De functie staat sinds 14 september op main en de eerste ochtendrun heeft gedraaid.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-15','nieuw','Algemeen','Meldingen op je telefoon over je acties, planning en uren',
   'EVA stuurt nu ook een melding als er een actie aan je wordt toegewezen, als er een toolbox voor je klaarstaat, als je planning voor de komende week verandert en als je weekstaat nog open staat. Projectleiders krijgen op maandagochtend bericht over de uren die op hun akkoord wachten. Je krijgt alleen bericht als er echt iets nieuws is: een stapel die je al kent blijft stil.');
